import math

def check_expression(n):
    # The expression is E(n) = 3 * ((n+2)! + 1) / (2n - 1)

    # Denominator check (should not be zero for non-negative integer n)
    denominator = 2 * n - 1
    if denominator == 0:
        return "Undefined (Denominator is zero)"

    try:
        # Numerator calculation
        factorial_term = math.factorial(n + 2)
        numerator = 3 * (factorial_term + 1)

        # Calculate the value
        result = numerator / denominator

        # Check if the result is an integer
        is_integer = result == int(result)

        return result, is_integer
    except OverflowError:
        return "Too large", False

solutions = []
results = {}

for n in range(11):
    result, is_integer = check_expression(n)
    results[n] = (result, is_integer)

    if is_integer:
        solutions.append(n)

print("Results for n=0 to n=10:")
for n, (result, is_integer) in results.items():
    if is_integer:
        print(f"n={n}: Value = {int(result)}, Integer = True (Solution)")
    else:
        print(f"n={n}: Value = {result}, Integer = False")

print("\nFound solutions:", solutions)

import math

def factorial_mod(k, p):
    res = 1
    for i in range(1, k + 1):
        res = (res * i) % p
    return res

# Test primes p = 2n - 1 for n in {15, 16, 19, 21, 22, 24}
# Condition: p | (( (p+5)/2 )! + 1) => (( (p+5)/2 )! mod p) == p - 1

tests = {
    29: 17,  # n=15. Check 17! mod 29
    31: 18,  # n=16. Check 18! mod 31
    37: 21,  # n=19. Check 21! mod 37
    41: 23,  # n=21. Check 23! mod 41
    43: 24,  # n=22. Check 24! mod 43
    47: 26   # n=24. Check 26! mod 47
}

results = {}
for p, k in tests.items():
    mod_k_fact = factorial_mod(k, p)
    is_solution = (mod_k_fact == p - 1)
    results[p] = {
        'n': (p + 1) // 2,
        'k': k,
        'mod_k_fact': mod_k_fact,
        'is_solution': is_solution
    }

print("--- Results for Prime Denominators ---")
for p, data in results.items():
    print(f"p={p} (n={data['n']}): Check {data['k']}! mod {p}")
    print(f"  {data['k']}! mod {p} = {data['mod_k_fact']}")
    print(f"  Solution: {data['is_solution']}\n")

import math

def check_congruence(p):
    # We check p | (( (p+5)/2 )! + 1)
    k = (p + 5) // 2

    # Calculate k! mod p
    if k < p:
        factorial_mod_p = 1
        for i in range(1, k + 1):
            factorial_mod_p = (factorial_mod_p * i) % p

        # Check if k! + 1 is divisible by p
        remainder = (factorial_mod_p + 1) % p

        if remainder == 0:
            return True, factorial_mod_p + 1
        else:
            return False, factorial_mod_p + 1
    else:
        # Since p > 5, k = (p+5)/2 < p, so this path shouldn't be hit for primes > 5.
        # If p=5, k=5, k! mod 5 = 0. (0+1)%5 = 1. Fails.
        return False, None

primes_to_check = [29, 31, 37, 41, 43, 47]
solutions = []

print("--- Checking primes p > 23 ---")
for p in primes_to_check:
    is_solution, value = check_congruence(p)
    if is_solution:
        solutions.append(p)
        print(f"p={p} (n={(p-1)/2}): SOLUTION found. k!+1 = {value}")
    else:
        print(f"p={p} (n={(p-1)/2}): Fails. k!+1 mod {p} = {value % p}")

print("\nKnown solutions: 7, 23.")
if solutions:
    print(f"New solutions found: {solutions}")
else:
    print("No new solutions found in the tested range.")

